import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n], b = new long[n];
        long sa = 0, sb = 0;
        for (int i = 0; i < n; i++) sa += a[i] = nextLong();
        for (int i = 0; i < n; i++) sb += b[i] = nextLong();
        if (sa != sb || sa % 2 != 0) {
            System.out.println(0);
            return;
        }
        long left = 0, right = 0, half = sa / 2;
        int answer = 0;
        // both prefixes must hit half of the common total at the same cut
        for (int i = 0; i + 1 < n; i++) {
            left += a[i];
            right += b[i];
            if (left == half && right == half) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a, b := make([]int, n), make([]int, n)
	sa, sb := 0, 0
	for i := range a {
		a[i] = next()
		sa += a[i]
	}
	for i := range b {
		b[i] = next()
		sb += b[i]
	}
	if sa != sb || sa%2 != 0 {
		fmt.Println(0)
		return
	}
	left, right, half, answer := 0, 0, sa/2, 0
	// both prefixes must hit half of the common total at the same cut
	for i := 0; i+1 < n; i++ {
		left += a[i]
		right += b[i]
		if left == half && right == half {
			answer++
		}
	}
	fmt.Println(answer)
}
